// RESEARCH ONLY. No repository, database, or deployment is touched.
// Flatten the Hermes research result (keywords array) defensively so a
// plain array or a nested envelope both work, and expose it downstream
// as a REVIEW artifact for a human to approve.
const research = $input.first().json;
let keywords = research.keywords || research.data?.results?.[0]?.keywords || [];
if (Array.isArray(research)) keywords = research;
const fileText = JSON.stringify(keywords, null, 2);
return {
  json: { count: keywords.length, keywords },
  binary: {
    data: {
      data: Buffer.from(fileText).toString('base64'),
      mimeType: 'application/json',
      fileName: 'weekly-keywords.json'
    }
  }
};

// LOCAL STAGING ONLY. Generates a H U M A N approval queue from the
// research payload. Nothing here is applied: every item is marked
// NEEDS_REVIEW and the decision to write anything to the catalog or repo
// is deliberately left to an approved executor (Freebuff / the owner).
const item = $input.first().json;
const keywords = Array.isArray(item.keywords) ? item.keywords : [];
const guard = ['seo_keywords','seo_title','seo_description','slug'];
const queue = keywords.map((k, i) => ({
  ref: `wk-${new Date().toISOString().slice(0,10)}-${i+1}`,
  primaryKeyword: k.primary || k.focus || (typeof k === 'string' ? k : undefined) || 'unspecified',
  supporting: Array.isArray(k.supporting) ? k.supporting : [],
  intent: k.intent || 'informational',
  cluster: k.cluster || 'uncategorized',
  targetPage: k.slug || '',
  productCategory: k.category || '',
  cannibalizationRisk: Boolean(k.duplicate_of) ? k.duplicate_of : 'review',
  priority: k.priority || 3,
  status: 'NEEDS_REVIEW',
  reason: k.reason || 'queue for human review — no change applied',
  writeActions: guard.map(f => f).filter(f => Object.prototype.hasOwnProperty.call(k, f))
    .map(f => `would set ${f} on match`),
  applied: false
}));
const summary = {
  generated_at: new Date().toISOString(),
  mode: 'RESEARCH + APPROVAL ONLY',
  applied: 0,
  staged_artifacts: [ 'weekly-keywords.json', 'seo-approval-queue.json' ],
  next_step: 'Human reviews queue; approved rows are applied by an approved executor, never by n8n.'
};
const fileText = JSON.stringify({ summary, queue }, null, 2);
return {
  json: { summary, count: queue.length, queue },
  binary: {
    data: {
      data: Buffer.from(fileText).toString('base64'),
      mimeType: 'application/json',
      fileName: 'seo-approval-queue.json'
    }
  }
};

// Approval NOTIFICATION summary. Read-only: builds a short human-readable
// digest of staged opportunities. Reports the staging paths and makes explicit
// that NO catalog/repo change, git commit/push, or deploy was performed.
const item = $input.first().json;
const queue = Array.isArray(item.queue) ? item.queue : [];
const lines = queue.slice(0, 10).map((q) =>
  `- [NEEDS_REVIEW] ${q.primaryKeyword} (cluster: ${q.cluster}, intent: ${q.intent}, priority: ${q.priority}) target: ${q.targetPage || 'n/a'}`
);
const body =
  `Luxedge SEO weekly research complete — NO changes applied.\n` +
  `${queue.length} opportunity(ies) staged for human review.\n` +
  lines.join('\n') +
  `\nReview: .freebuff/weekly-keywords.json + .freebuff/seo-approval-queue.json` +
  `\nApply approved rows with an approved executor (Freebuff/owner). n8n does not commit or deploy.`;
return { json: { summary: item.summary, count: item.count, approval_digest: body } };
